import React from "react";
import { Link, useLocation } from "react-router-dom";
import "./Navbar.css";

export default function Navbar() {
  return (
    <nav className="nav">
      <ul className="nav-list">
        {/* Home stays active on / and /viewinfo */}
        <CustomLink to="/" activePaths={["/", "/viewinfo"]}>
          Home
        </CustomLink>

        {/* Landlord stays active on /landlord and /landlordinfo */}
        <CustomLink to="/landlord" activePaths={["/landlord", "/landlordinfo"]}>
          Landlord
        </CustomLink>

        <CustomLink to="/aboutUs">About</CustomLink>
        <CustomLink to="/contactUs">Contact Us</CustomLink>
      </ul>

      <div className="profile-icon">
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width="40"
          height="40"
          fill="white"
          viewBox="0 0 24 24"
        >
          <circle cx="12" cy="8" r="4" />
          <path d="M12 14c-5 0-9 4-9 9h18c0-5-4-9-9-9z" />
        </svg>
      </div>
    </nav>
  );
}

function CustomLink({ to, activePaths = [], children, ...props }) {
  const { pathname } = useLocation();

  // Match exactly for root or partial for custom subpaths
  const isActive =
    activePaths.includes(pathname) ||
    activePaths.some((path) => pathname.startsWith(path + "/"));

  return (
    <li className={isActive ? "active-link" : ""}>
      <Link to={to} {...props}>
        {children}
      </Link>
    </li>
  );
}
